def build():
    for name, (title, description, steps, command, example) in SKILLS.items():
        directory = ROOT/"skills"/name
        (directory/"references").mkdir(parents=True, exist_ok=True)
        (directory/"agents").mkdir(exist_ok=True)
        front = yaml.safe_dump({"name": name, "description": description}, allow_unicode=True, sort_keys=False).strip()
        body = f"---\n{front}\n---\n\n# {title}\n\n## 触发场景\n\n{description}\n\n## 输入要求\n\n用户制作目标、项目路径、原文或Episode JSON，以及对应的已有角色图/场景/工作流。具体读取 [共享工具说明](references/shared_tools.md)。\n\n## 工作步骤\n\n" + "\n".join(f"{i}. {step}" for i, step in enumerate(steps, 1))
        body += f"\n\n## 输出格式\n\n共享 CLI 产生的JSON、Markdown与真实PNG及状态；报告实际路径、审批状态、测试范围和缺失能力。创作数据遵守项目 `templates/episode.schema.json` 与 `templates/image_prompt.schema.json`。\n\n## 使用的工具\n\n优先已安装的 `ai-drama` 或项目 `scripts/ai-drama.ps1`；执行逻辑统一使用 `src/ai_drama`。需要视觉确认时读取实际图片。\n\n## 错误处理\n\n缺输入先读取已有项目；真正影响结果的缺项再询问。环境离线可处理剧本与导出，不能声称真实出图。模型节点缺失报告能力，不擅自下载、安装、升级。未审批角色停在候选状态。任务超时按记录恢复，原素材与原工作流另存保留。\n\n## 使用示例\n\n用户：{example}\n\n```powershell\n.\\scripts\\ai-drama.ps1 {command}\n```\n"
        (directory/"SKILL.md").write_text(body, encoding="utf-8")
        (directory/"agents"/"openai.yaml").write_text(yaml.safe_dump({"interface": {"display_name": title, "short_description": description[:62], "default_prompt": f"使用 ${name} 在当前 AI Drama Studio 项目中完成对应制作任务。"}}, allow_unicode=True, sort_keys=False), encoding="utf-8")
        (directory/"references"/"shared_tools.md").write_text("# 共享工具层\n\n定位用户的 ai-drama-skills 项目，不假定跨机器的绝对路径。先读取该项目 README.md、AGENTS.md、docs/cli.md、docs/architecture.md。项目级副本只负责发现，源技能位于 skills/，通过 scripts/install_skills.py 同步。\n\n在项目根目录运行 scripts/ai-drama.ps1；其他生产项目使用全局参数 --project <path>，共享工作流库通过 --library <path>。全部全局参数放在子命令之前。使用 --help 查真实参数，读取 templates/*.schema.json 编写数据。\n\n脚本负责状态持久化和检查，Codex负责语义创作与视觉判断；不调用付费LLM或视频API。--snapshot 是离线验证，不是运行验证。\n", encoding="utf-8")
    return len(SKILLS)


if __name__ == "__main__":
    print(build())
